241	    /**
242	     * Maximum number of owners allowed in a single city. Creating an owner in a city that has
243	     * already reached this many owners is rejected as a conflict.
244	     */
245	    static final int MAX_OWNERS_PER_CITY = 50;
246	
247	    /**
248	     * Maximum number of owners allowed to register on a single day. Creating an owner once a day has
249	     * already reached this many registrations is rejected as a rate-limit violation.
250	     */
251	    static final int MAX_OWNERS_PER_DAY = 100;
252	
253	    /**
254	     * Number of owners that must already have registered on a day before a new registration is
255	     * flagged with a bulk-signup warning. Once the count already recorded for the day exceeds this
256	     * value, the new owner carries {@code bulkSignupWarning == true}.
257	     */
258	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
259	
260	    @Override
261	    @Transactional
262	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
263	        if (ownerRepository.existsByTelephone(owner.getTelephone())) {
264	            throw new DuplicateTelephoneException(owner.getTelephone());
265	        }
266	        List<Owner> householdMembers = findHouseholdMembers(owner);
267	        if (!householdMembers.isEmpty() && !sharesHousehold) {
268	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
269	        }
270	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
271	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
272	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
273	        }
274	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
275	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
276	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
277	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
278	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
279	        }
280	        owner.setBulkSignupWarning(ownersOnDate > BULK_SIGNUP_WARNING_THRESHOLD);
281	        owner.setNamesakeCount(countNamesakes(owner));
282	        owner.setHouseholdSize(householdMembers.size() + 1);
283	        owner.setCustomerCode(CustomerCodeGenerator.format(
284	            owner.getCity(), owner.getLastName(), ownersInCity + 1));
285	        if (!householdMembers.isEmpty()) {
286	            owner.setHouseholdId(joinHousehold(owner, householdMembers));
287	        }
288	        ownerRepository.save(owner);
289	        ownerAuditLogger.ownerCreated(owner);
290	        return owner.getHouseholdId();
291	    }
292	
293	    /**
294	     * Assign the stable household identifier to the new owner and to every existing member of the
295	     * household, persisting the members whose identifier changes, and return the shared identifier.
296	     */
297	    private String joinHousehold(Owner owner, List<Owner> householdMembers) {
298	        String householdId = HouseholdIdGenerator.generate(owner.getLastName(), owner.getAddress());
299	        for (Owner member : householdMembers) {
300	            if (!householdId.equals(member.getHouseholdId())) {
301	                member.setHouseholdId(householdId);
302	                ownerRepository.save(member);
303	            }
304	        }
305	        return householdId;
306	    }
307	
