314	    /**
315	     * Count the owners that already exist sharing this owner's first name and last name, compared
316	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
317	     */
318	    private int countNamesakes(Owner owner) {
319	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
320	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
321	            .count();
322	    }
323	
324	    /**
325	     * Find the existing owners that already share this owner's household, i.e. that have the same last name and
326	     * address compared case-insensitively and with runs of whitespace collapsed.
327	     */
328	    private List<Owner> findHouseholdMembers(Owner owner) {
329	        String address = TextNormalizer.normalize(owner.getAddress());
330	        if (address == null) {
331	            return List.of();
332	        }
333	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
334	            .filter(existing -> address.equals(TextNormalizer.normalize(existing.getAddress())))
335	            .toList();
336	    }
