353	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
354	    }
355	
356	    private <T> T findEntityById(Supplier<T> supplier) {
357	        try {
358	            return supplier.get();
359	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
360	            // Just ignore not found exceptions for Jdbc/Jpa realization
361	            return null;
362	        }
363	    }
364	
365	}
